    'c.cv.b': 'اینجا رزومه کوتاه است: ۱ یا ۲ صفحه. اطلاعات تماس، سابقهٔ کار، تحصیلات، زبان‌ها و مهارت‌هایت را بنویس. عکس لازم نیست. لازم نیست دین، سن یا وضعیت تأهلت را بنویسی. دربارهٔ کارهایی که بلدی صادق باش. از کسی بخواه هلندی‌ات را بررسی کند.', // nieuw, nalezen // nagelezen AI 22 nov
