    'c.interview': 'مصاحبهٔ کاری',
    'c.interview.b': 'سر وقت برو: ۵ تا ۱۰ دقیقه زودتر. مؤدبانه سلام کن و به طرف نگاه کن. کوتاه بگو چه کارهایی بلدی. سؤال پرسیدن از طرف خودت عادی و خوب است، مثلاً دربارهٔ ساعت‌ها، کار یا آموزش. آخر کار می‌توانی بپرسی کی خبر می‌گیری. اشکالی ندارد بگویی هنوز داری هلندی یاد می‌گیری. کارفرما اجازه ندارد دربارهٔ دین، بارداری یا سلامتی‌ات بپرسد. لازم نیست جواب بدهی: می‌توانی مؤدبانه بگویی ترجیح می‌دهی جواب ندهی.',
