    'c.kitchen.o3': 'به مهمان بگو مغزهای آجیلی را خودش جدا کند.',
    'c.kitchen.w': 'برای مهمانی که حساسیت دارد، یک اشتباه کوچک می‌تواند خیلی خطرناک باشد. پرسیدن از سرآشپز همیشه درست است.',
    'c.service': 'مؤدب با مهمان‌ها',
    'c.service.b': 'به مهمان‌ها «u» بگو، مگر اینکه از تو بخواهند «je» بگویی. مهربان و آرام باش، حتی وقتی شلوغ است. جواب سؤالی را مطمئن نیستی؟ بگو بررسی می‌کنی. انعام (fooi): قانون‌ها در هر جا فرق دارد. بپرس در محل کارت انعام چطور تقسیم می‌شود.',
