    'c.cleaning': 'برچسب را بخوان',
    'c.cleaning.b': 'هر مادهٔ شوینده برچسب دارد. علامت‌ها (تصویرهای کوچک در یک لوزی قرمز) خطر را نشان می‌دهند، مثلاً برای پوست، چشم یا ریه‌هایت. برچسب را بخوان، یا بپرس این ماده برای چیست و چطور از آن استفاده کنی. دستکشی را که کارفرما به تو می‌دهد بپوش. قانون‌ها در هر شرکت فرق دارد: از سرپرستت بپرس قانون‌های محل کارت چیست.',
