    'c.cleansafe.b': 'هیچ‌وقت مواد شوینده را با هم مخلوط نکن، مثلاً وایتکس و جرم‌گیر توالت. این کار می‌تواند گاز خطرناک درست کند. پنجره را باز کن تا هوای تازه بیاید. زمین را تی می‌کشی؟ تابلوی «زمین خیس» (Pas op, glad!) را بگذار، تا کسی لیز نخورد. قانون‌ها در هر شرکت فرق دارد: از سرپرستت بپرس قانون‌های محل کارت چیست.',
