    'c.translate': 'اپ‌های ترجمه: هوشمند، ولی بررسی کن',
    'c.translate.b': 'یک اپ ترجمه، مثل Google Translate، خیلی کمک می‌کند. می‌توانی تایپ کنی، حرف بزنی، یا از حالت مکالمه استفاده کنی تا با یک همکار صحبت کنی. با دوربین می‌توانی تابلوها، یادداشت‌ها و دستورالعمل‌ها را ترجمه کنی. در خیلی از گوشی‌ها، WhatsApp هم می‌تواند پیام‌ها را ترجمه کند. فقط جایی از گوشی‌ات استفاده کن که ایمن و مجاز است. هیچ‌وقت نزدیک دستگاه‌ها یا لیفتراک‌ها از آن استفاده نکن. همیشه اول بپرس. اپ‌ها اشتباه می‌کنند. برای چیزهای مهم، مثل قراردادت، یک نامه یا یک دستورالعمل ایمنی، از یک آدم هم بخواه آن را توضیح بدهد. بدون اجازه از کاغذهای محرمانهٔ کار عکس نگیر.',
    'c.translate.p': 'اجازه هست برای ترجمه از گوشی‌ام استفاده کنم؟',
    'c.translate.s': 'سرپرستت دستورالعمل‌های ایمنی به هلندی به تو می‌دهد. فقط چند کلمه را می‌فهمی. چه کار می‌کنی؟', // nieuw, nalezen (AI-correctie 2 nov 2026) // nagelezen AI 22 nov
    'c.translate.o1': 'توضیح بخواه، و بپرس استفاده از اپ اشکالی ندارد.', // nieuw, nalezen (AI-correctie 2 nov 2026) // nagelezen AI 22 nov
    'c.translate.o2': 'بگو «ja, ja» و کار را شروع کن.', // nieuw, nalezen (AI-correctie 2 nov 2026) // nagelezen AI 22 nov
    'c.translate.o3': 'از آن عکس بگیر و برای دوستانت بفرست تا ترجمه‌اش کنند.', // nieuw, nalezen (AI-correctie 2 nov 2026) // nagelezen AI 22 nov
    'c.translate.w': 'اپ ترجمه کمک می‌کند زود بفهمی، ولی ممکن است اشتباه کند. برای ایمنی، توضیح یک آدم بهترین راه بررسی است. کاغذهای کار ممکن است محرمانه باشند، پس بدون اجازه آن‌ها را با کسی به اشتراک نگذار.',
    'c.understood': 'بررسی کن که درست فهمیدی',
    'c.understood.b': 'گوشی‌ات می‌تواند حرف را به متن تبدیل کند (زیرنویس زنده): Live Transcribe در Android، و Live Captions در iPhone. ببین گوشی‌ات از چه زبان‌هایی پشتیبانی می‌کند. همچنین می‌توانی از کسی بخواهی آن را بنویسد، نشانت بدهد، یا آرام حرف بزند. بپرس آیا دستورالعملی با تصویر، یا به زبان خودت، هست. بعد چیزی را که فهمیدی دوباره بگو: «Dus ik moet eerst …?» (پس اول باید …؟). این کار اینجا عادی است، و جلوی اشتباه را می‌گیرد.',
    'c.understood.p': 'پس اول باید جعبه‌ها را بشمارم؟',
    'c.understood.s': 'یک همکار توضیح می‌دهد که یک دستگاه جدید چطور کار می‌کند. او تند حرف می‌زند و چند کلمه را نمی‌فهمی. چه کار می‌کنی؟',
    'c.understood.o1': 'از او بخواه نشانت بدهد یا بنویسد، بعد آن را دوباره بگو.', // nagelezen (2e lezing) // nagelezen AI 22 nov
    'c.understood.o2': 'سر تکان بده و بگو «ja, ja»، تا وقتش هدر نرود.',
    'c.understood.o3': 'بعداً تنهایی دستگاه را امتحان کن و ببین چه می‌شود.',
    'c.understood.w': 'نشان دادن، نوشتن و دوباره گفتن، راه‌های سریع بررسی هستند. همکارت می‌تواند قبل از اینکه چیزی خراب شود، اشتباهت را درست کند. اینجا این کار دقت حساب می‌شود، نه کندی.',
    'c.keeplearning': 'به یادگیری ادامه بده، هر روز کمی',
    'c.keeplearning.b': 'هر روز چند دقیقه بیشتر از یک ساعت طولانی در هفته کمک می‌کند. کلمه‌های جدید سر کار را در یک اپ یادداشت روی گوشی‌ات ذخیره کن. به هلندی ساده گوش بده، مثلاً NOS Jeugdjournaal (اخبار برای بچه‌ها) یا یک پادکست به هلندی آرام. خیلی از کتابخانه‌های عمومی یک Taalhuis دارند: کمک رایگان برای هلندی، اغلب با یک taalcafé (جایی برای تمرین حرف زدن) یا یک همراه زبان (taalmaatje). همکاران اغلب زبان را به انگلیسی عوض می‌کنند تا به تو کمک کنند. با مهربانی از آن‌ها بخواه با تو هلندی حرف بزنند: بیشتر آدم‌ها دوست دارند کمک کنند.',
    'c.keeplearning.p': 'فقط با من هلندی حرف بزن، این‌طوری زودتر یادش می‌گیرم.',
    'c.keeplearning.s': 'همکارانت وقتی با تو حرف می‌زنند، همیشه زبان را به انگلیسی عوض می‌کنند. می‌خواهی هلندی یاد بگیری. چه کار می‌کنی؟',
    'c.keeplearning.o1': 'از آن‌ها تشکر کن، و بخواه با تو هلندی حرف بزنند.', // nagelezen (2e lezing) // nagelezen AI 22 nov
