    'c.gossip': "غیبت و شبکه‌های اجتماعی",
    'c.gossip.b': "حرف زدن پشت سر یک همکار (roddelen) به اعتماد در تیم آسیب می‌زند. با کسی مشکل داری؟ با خود آن شخص یا با سرپرستت حرف بزن. در فضای آنلاین هم همان قانون‌های محل کار برقرار است. بدون اجازه هیچ چیزی دربارهٔ همکاران، مشتری‌ها یا شرکت پست نکن. این شامل عکس، ویدیو و پیام هم می‌شود. رئیست می‌تواند ببیند تو چه پست می‌کنی، و ممکن است سال‌ها آنلاین بماند. خیلی از تیم‌ها یک گروه چت (groepsapp) برای کار دارند: آن را فقط برای کار نگه دار و از آن اسکرین‌شات برای دیگران نفرست. پخش کردن چیزهای خصوصی یک همکار یا مسخره کردن کسی در فضای آنلاین هم آزار و قلدری است.",
    'c.gossip.p': "نمی‌خواهم این آنلاین باشد.",
    'c.gossip.s': "یک همکار وقتی روی زمین خیس لیز می‌خوری از تو فیلم می‌گیرد. او می‌خواهد ویدیو را در TikTok بگذارد. چه کار می‌کنی؟",
    'c.gossip.o1': 'بگو "Nee, dat wil ik niet" و از او بخواه آن را پاک کند.', // nagelezen (2e lezing) // nagelezen AI 22 nov
    'c.gossip.o2': "بخند و بگذار پستش کند، تا آدم سخت‌گیری به نظر نرسی.",
    'c.gossip.o3': 'از او بخواه آن را بدون اسم تو پست کند.', // nagelezen (2e lezing) // nagelezen AI 22 nov
    'c.gossip.w': 'معمولاً هیچ‌کس اجازه ندارد بدون اجازهٔ تو ویدیویی از تو را آنلاین بگذارد. «نه» گفتن عادی است، و کارفرمایت باید وقتی همکاران در فضای آنلاین همدیگر را مسخره می‌کنند، کاری بکند. اگر باز هم آن را پست کرد، به سرپرستت بگو.', // nieuw, nalezen // nagelezen AI 22 nov
    'c.boundaries': "عبور از حد و مرز",
    'c.boundaries.b': "Grensoverschrijdend gedrag رفتاری است که از مرز کسی عبور می‌کند. مثلاً: لمس ناخواسته، حرف‌ها یا شوخی‌های جنسی، خیره شدن، عکس‌های ناخواسته، تهدید یا داد زدن. مهم نیست که طرف مقابل \"منظورش شوخی بود\": مهم این است که تو چه حسی داری. اگر می‌توانی، واضح بگو که می‌خواهی این کار تمام شود. بنویس چه اتفاقی افتاد، کی، و چه کسی آن را دید. به سرپرستت، مشاور معتمد (vertrouwenspersoon، اگر وجود داشته باشد) یا HR بگو. کارفرمایت باید از تو محافظت کند، و نباید به خاطر گزارش دادن تنبیه شوی. دیدی این اتفاق برای یک همکار افتاد؟ از او بپرس حالش خوب است یا نه، و پیشنهاد بده که شاهد باشی.",
    'c.boundaries.p': "می‌خواهم تمامش کنی.",
