    'c.shelves.w': 'مشتری‌ها از جلو برمی‌دارند. وقتی محصولات قدیمی اول فروخته شوند، غذای کمتری دور ریخته می‌شود.',
    'c.checkout': 'کارت شناسایی برای الکل و دخانیات',
    'c.checkout.b': 'نباید به کسی که زیر ۱۸ سال است الکل یا دخانیات بفروشی: این قانون است. مطمئن نیستی مشتری چند سال دارد؟ کارت شناسایی‌اش را بخواه. خیلی از فروشگاه‌ها از هر کسی که جوان‌تر از ۲۵ سال به نظر می‌رسد کارت شناسایی می‌خواهند. کارت شناسایی ندارد، یا زیر ۱۸ سال است؟ پس به او نفروش، و مؤدب بمان. قانون‌ها در هر شرکت فرق دارد: از سرپرستت بپرس قانون‌های محل کارت چیست.',
    'c.checkout.p': 'بدون کارت شناسایی اجازه ندارم این را بفروشم.',
    'c.checkout.s': 'یک مرد جوان می‌خواهد آبجو بخرد. به نظر حدود ۱۷ ساله است. می‌گوید ۱۹ سال دارد، اما کارت شناسایی همراهش نیست. چه کار می‌کنی؟',
    'c.checkout.o1': 'بگو بدون کارت شناسایی نمی‌توانی بفروشی.', // nagelezen (2e lezing) // nagelezen AI 22 nov
    'c.checkout.o2': 'به او بفروش، چون می‌گوید ۱۹ سال دارد.',
    'c.checkout.o3': 'به او بفروش، اما فقط یک قوطی.',
    'c.checkout.w': 'بدون کارت شناسایی نمی‌توانی بدانی چند سال دارد. فروش الکل به کسی که زیر ۱۸ سال است خلاف قانون است، و فروشگاه ممکن است جریمه شود.',
    'c.counting': 'Vijfentwintig: اول ۵، بعد ۲۰', // nieuw, nalezen // nagelezen AI 22 nov
    'c.counting.b': 'در هلندی، عددهای ۰ تا ۱۲ هر کدام کلمهٔ خودشان را دارند: nul، een، twee، drie، vier، vijf، zes، zeven، acht، negen، tien، elf، twaalf. عددهای ۱۳ تا ۱۹ با -tien تمام می‌شوند: dertien، veertien، vijftien، zestien، zeventien، achttien، negentien. دهگان‌ها با -tig تمام می‌شوند: twintig، dertig، veertig، vijftig، zestig، zeventig، tachtig، negentig. از ۲۱ تا ۹۹ اول رقم آخر را می‌گویند: ۲۵ می‌شود vijfentwintig، یعنی «پنج و بیست». پس ۴۷ می‌شود zevenenveertig و ۷۴ می‌شود vierenzeventig. Dertien و dertig تقریباً یکسان شنیده می‌شوند: به آخرش گوش بده. مطمئن نیستی؟ رقم‌ها را یکی‌یکی تکرار کن.', // nieuw, nalezen // nagelezen AI 22 nov
    'c.counting.p': 'چهار، هفت؟ یعنی چهل و هفت؟', // nieuw, nalezen // nagelezen AI 22 nov
    'c.counting.s': 'سرپرستت می‌گوید: «Ga naar gang zevenenveertig.» کدام راهرو است؟', // nieuw, nalezen // nagelezen AI 22 nov
    'c.counting.o1': 'راهروی ۴۷.', // nieuw, nalezen // nagelezen AI 22 nov
    'c.counting.o2': 'راهروی ۷۴.', // nieuw, nalezen // nagelezen AI 22 nov
    'c.counting.o3': 'راهروی ۴۰.', // nieuw, nalezen // nagelezen AI 22 nov
    'c.counting.w': '«Zevenenveertig» یعنی «هفت و چهل»: اول ۷، بعد ۴۰. پس راهروی ۴۷ است. خیلی از تازه‌واردها ۷۴ می‌شنوند و به راهروی اشتباه می‌روند.', // nieuw, nalezen // nagelezen AI 22 nov
    'c.hours': '«Half acht» یعنی ۷:۳۰',
    'c.hours.b': 'در هلندی، «half» تا ساعت بعدی حساب می‌شود: half acht یعنی ۷:۳۰، نه ۸:۳۰. Kwart over acht یعنی ۸:۱۵، و kwart voor acht یعنی ۷:۴۵. ساعت‌های کارت را خودت حساب کن: ساعت پایان منهای ساعت شروع، منهای استراحت. برای استراحت اغلب پولی پرداخت نمی‌شود. ساعت‌های کارت را هر روز یادداشت کن.',
    'c.hours.p': '«Half acht»؟ یعنی نیم ساعت قبل از هشت؟',
    'c.hours.s': 'سرپرستت می‌گوید: «Morgen begin je om half negen.» فردا ساعت چند شروع می‌کنی؟',
    'c.hours.o1': 'ساعت ۸:۳۰.',
    'c.hours.o2': 'ساعت ۹:۳۰.',
    'c.hours.o3': 'ساعت ۸:۰۰.',
    'c.hours.w': '«Half negen» یعنی نیم ساعت قبل از نه: ۸:۳۰. خیلی از تازه‌واردها فکر می‌کنند ۹:۳۰ است، و یک ساعت دیر می‌آیند.',
    'c.measures': 'هوشمندانه بشمار، اندازه بگیر، حدس نزن',
    'c.measures.b': 'باید جعبه‌های زیادی بشماری؟ جعبه‌های یک لایه را بشمار، و تعداد لایه‌ها را. بعد ضرب کن: ۸ جعبه در هر لایه و ۵ لایه می‌شود ۴۰ جعبه. برای مواد شوینده، همان مقداری را که روی برچسب نوشته شده اندازه بگیر. بیشتر بهتر نیست: می‌تواند به پوستت آسیب بزند و پول هدر می‌دهد. از عددی مطمئن نیستی؟ دوباره بشمار، یا بپرس. قانون‌ها در هر شرکت فرق دارد: از سرپرستت بپرس قانون‌های محل کارت چیست.',
    'c.measures.p': 'دو بار شمردمش.',
    'c.measures.s': 'یک پالت ۶ لایه دارد. هر لایه ۸ جعبه دارد. سرپرستت می‌پرسد چند جعبه هست. چه می‌گویی؟',
