    'c.aiplan.a': 'می‌توانم دربارهٔ آن با یک آدم حرف بزنم؟',
    'c.aihelp': 'هوش مصنوعی کمک می‌کند، یک آدم بررسی می‌کند',
    'c.aihelp.b': 'اپ‌های هوش مصنوعی و چت‌بات‌ها، مثل ChatGPT، می‌توانند ترجمه کنند، یک نامه را توضیح بدهند یا در نوشتن پیام کمکت کنند. این مفید است. اما هوش مصنوعی گاهی اشتباه می‌کند و باز هم خیلی مطمئن به نظر می‌رسد. موضوع دربارهٔ قراردادت، حقوقت، دارو یا ایمنی است؟ پس همیشه جواب را با یک آدم بررسی کن. مثلاً با سرپرستت، بخش منابع انسانی (HR) یا Juridisch Loket.',
    'c.aihelp.p': 'این درست است؟ می‌شود با من یک نگاهی بیندازید؟',
    'c.aihelp.s': 'از یک چت‌بات دربارهٔ قراردادت می‌پرسی. می‌گوید پول تعطیلات (vakantiegeld) نمی‌گیری. چه کار می‌کنی؟',
    'c.aihelp.o1': 'از HR یا Juridisch Loket بخواه بررسی‌اش کنند.', // nagelezen (2e lezing) // nagelezen AI 22 nov
    'c.aihelp.o2': 'باورش کن: چت‌بات خیلی مطمئن به نظر می‌رسد.',
    'c.aihelp.o3': 'چیزی نگو و فراموشش کن.',
    'c.aihelp.w': 'چت‌بات ممکن است دربارهٔ قانون‌ها و قراردادها اشتباه کند. در هلند تقریباً هر کارگری پول تعطیلات می‌گیرد. کسی که قانون‌ها را می‌داند می‌تواند آن را بررسی کند.',
    'c.aiprivate': 'قبل از تایپ کردن فکر کن',
    'c.aiprivate.b': 'هر چیزی که در یک چت‌بات تایپ می‌کنی ممکن است ذخیره شود و شرکت سازندهٔ آن از آن استفاده کند. پس هرگز BSN، رمز عبور یا اطلاعات بانکی‌ات را تایپ نکن. اسم یا عکس مشتری‌ها، بیمارها یا همکارها، یا کاغذهای کاری را هم وارد نکن. خیلی از کارفرماها برای هوش مصنوعی قانون دارند. اول بپرس که اجازه داری برای کارت از آن استفاده کنی یا نه. قانون‌ها در هر شرکت فرق دارد: از سرپرستت بپرس قانون‌های محل کارت چیست.',
    'c.aiprivate.p': 'اجازه دارم برای این از هوش مصنوعی استفاده کنم؟',
    'c.aiprivate.s': 'می‌خواهی یک چت‌بات دربارهٔ یک مشتری گزارش بنویسد. در گزارش اسم و نشانی مشتری هست. چه کار می‌کنی؟',
    'c.aiprivate.o1': 'اول بپرس و اسم و نشانی را حذف کن.', // nagelezen (2e lezing) // nagelezen AI 22 nov
    'c.aiprivate.o2': 'همه‌چیز را در چت‌بات بگذار: سریع‌تر است.',
    'c.aiprivate.o3': 'گزارش را برای یک دوست بفرست تا بررسی‌اش کند.',
    'c.aiprivate.w': 'اسم‌ها و نشانی‌ها اطلاعات شخصی هستند. نباید همین‌طوری به یک شرکت دیگر بروند. کارفرمایت می‌داند کدام اپ‌ها مجاز هستند.',
    'c.aifake': 'صداها و ویدیوهای جعلی',
    'c.aifake.b': 'با هوش مصنوعی، کلاهبردارها می‌توانند صدای کسی را کپی کنند و عکس و ویدیوی جعلی بسازند. تماس یا پیامی که شبیه رئیست، بانکت یا یکی از خانواده‌ات است ممکن است جعلی باشد. وقتی عجله، پول و یک شمارهٔ جدید در کار است، مراقب باش. قطع کن و خودت به شماره‌ای که می‌شناسی زنگ بزن. یک بانک، کارفرما یا پلیس واقعی هیچ‌وقت کدهایت را نمی‌خواهد.',
    'c.aifake.p': 'قطع می‌کنم و خودم دوباره زنگ می‌زنم.',
    'c.aifake.s': 'تلفنت زنگ می‌زند. صدایی که دقیقاً مثل صدای رئیست است می‌گوید: «این صورت‌حساب را همین الان پرداخت کن، فوری است.» چه کار می‌کنی؟',
    'c.aifake.o1': 'قطع کن و خودت به رئیست زنگ بزن.', // nagelezen (2e lezing) // nagelezen AI 22 nov
    'c.aifake.o2': 'زود پرداخت کن: رئیست است دیگر.',
    'c.aifake.o3': 'کد بانکی‌ات را بده تا رئیست بتواند پرداخت کند.',
    'c.aifake.w': 'صدا را می‌شود با هوش مصنوعی کپی کرد. عجله و پول با هم یک علامت هشدار است. زنگ زدن به شماره‌ای که می‌شناسی یک بررسی سریع و امن است.',
    'c.aiplan': 'چه کسی این را تصمیم گرفت؟',
    'c.aiplan.b': 'شرکت‌های بیشتر و بیشتری می‌گذارند یک اپ یا کامپیوتر دربارهٔ چیزها تصمیم بگیرد. مثلاً برنامهٔ کاری را می‌سازد یا سرعتت را با اسکنر اندازه می‌گیرد. می‌توانی بپرسی چه اطلاعاتی دربارهٔ تو جمع می‌شود. تصمیم مهمی دربارهٔ تو گرفته شده، مثل ساعت‌های کمتر، یک اخطار یا اخراج؟ بپرس چه کسی آن را تصمیم گرفت. یک کامپیوتر آن تصمیم را به تنهایی گرفته؟ پس می‌توانی بخواهی که یک آدم دوباره آن را بررسی کند و توضیحش بدهد. ساعت‌های کارت را خودت یادداشت کن. اطلاعات کلی. برای وضعیت خودت: از کارفرما، اتحادیهٔ کارگری یا Juridisch Loket بپرس.',
    'c.aiplan.p': 'می‌شود یک آدم به این نگاهی بیندازد؟',
    'c.aiplan.s': 'اپ برنامه‌ریزی ماه بعد ساعت‌های خیلی کمتری به تو می‌دهد. هیچ‌کس نمی‌گوید چرا. چه کار می‌کنی؟',
    'c.aiplan.o1': 'بخواه که یک آدم توضیحش بدهد.', // nagelezen (2e lezing) // nagelezen AI 22 nov
    'c.aiplan.o2': 'قبولش کن: اپ همیشه درست می‌گوید.',
    'c.aiplan.o3': 'از چت‌بات داخل اپ بپرس چرا.', // nagelezen (2e lezing) // nagelezen AI 22 nov
    'c.aiplan.w': 'اپ‌ها اشتباه می‌کنند و همه‌چیز را دربارهٔ تو نمی‌دانند. می‌توانی توضیح بخواهی، و یک آدم می‌تواند دوباره به آن نگاه کند.',
