    's.greensafe.3': "چرخ برداشت کجاست؟", // nagelezen (2e lezing)
    'c.greensafe.q': "می‌توانم در گلخانهٔ سه کار کنم؟", // nagelezen (2e lezing)
    'c.greensafe.a': "نه، هنوز نه. تازه سم‌پاشی شده.", // nagelezen (2e lezing)
    'c.harvest': "سرعت کار و مزد کارمزدی", // nagelezen (2e lezing) // nagelezen AI 22 nov
    'c.harvest.b': "در گلخانه اغلب با یک سرعت ثابت (tempo) کار می‌کنی. بعضی کارفرماها برای هر جعبه، هر ردیف یا هر کیلو پول می‌دهند: این مزد کارمزدی (stukloon) است. حتی با مزد کارمزدی باید برای هر ساعتی که کار می‌کنی دست‌کم حداقل دستمزد را بگیری. مبلغ را در rijksoverheid.nl ببین. هر روز ساعت‌ها و جعبه‌هایت را یادداشت کن و با فیش حقوقی‌ات مقایسه کن. تند کار کردن خوب است، ولی ایمن کار کردن مهم‌تر است. اطلاعات کلی. برای وضعیت خودت: از اتحادیهٔ کارگری، Juridisch Loket یا FairWork بپرس.", // nagelezen (2e lezing) // nagelezen AI 22 nov
    'c.harvest.p': "امروز چند جعبه انجام دادم؟", // nagelezen (2e lezing) // nagelezen AI 22 nov
    'c.harvest.s': "برای هر جعبه به تو پول می‌دهند. این هفته ساعتی کمتر از حداقل دستمزد پول می‌گیری. چه کار می‌کنی؟", // nieuw, nalezen (AI-correctie 2 nov 2026) // nagelezen AI 22 nov
    'c.harvest.o1': "فهرست خودت از ساعت‌ها و جعبه‌ها را نشان بده.", // nieuw, nalezen (AI-correctie 2 nov 2026) // nagelezen AI 22 nov
    'c.harvest.o2': "چیزی نگو و تندتر کار کن.", // nieuw, nalezen (AI-correctie 2 nov 2026) // nagelezen AI 22 nov
    'c.harvest.o3': "قبول کن: با مزد کارمزدی این عادی است.", // nieuw, nalezen (AI-correctie 2 nov 2026) // nagelezen AI 22 nov
    'c.harvest.w': "با مزد کارمزدی هم باید برای هر ساعتی که کار کرده‌ای دست‌کم حداقل دستمزد را بگیری. فهرست خودت از ساعت‌ها و جعبه‌ها کمک می‌کند نشان بدهی چه کار کرده‌ای. اگر درست نشد، کمک بخواه.", // nagelezen (2e lezing) // nagelezen AI 22 nov
    'c.greensafe': "گرما و سم‌ها", // nagelezen (2e lezing) // nagelezen AI 22 nov
    'c.greensafe.b': "در گلخانه هوا می‌تواند خیلی گرم شود، حتی در بهار. زیاد آب بخور، حتی قبل از اینکه تشنه شوی، و استراحتت را در جای خنک بکن. سرگیجه داری، حالت تهوع داری یا سرت درد می‌کند؟ دست نگه دار و به کسی بگو. گیاهان گاهی با مواد شیمیایی سم‌پاشی می‌شوند (spuitmiddelen). روی در گلخانه‌ای که تازه سم‌پاشی شده اغلب یک تابلو هست. تا وقتی سرپرستت نگفته که دوباره ایمن است، داخل نرو. اطلاعات کلی. برای وضعیت خودت: از کارفرما، اتحادیهٔ کارگری یا Juridisch Loket بپرس.", // nagelezen (2e lezing) // nagelezen AI 22 nov
    'c.greensafe.p': "الان می‌توانم در این گلخانه کار کنم؟", // nagelezen (2e lezing) // nagelezen AI 22 nov
    'c.greensafe.s': "امروز صبح یک گلخانه سم‌پاشی شده. روی در یک تابلو هست. یک همکار می‌گوید: «بیا، فقط یک لحظه است.» چه کار می‌کنی؟", // nagelezen (2e lezing) // nagelezen AI 22 nov
    'c.greensafe.o1': "بیرون بمان و بپرس کی ایمن است.", // nagelezen (2e lezing) // nagelezen AI 22 nov
    'c.greensafe.o2': "زود برو داخل و نفست را نگه دار.", // nagelezen (2e lezing) // nagelezen AI 22 nov
    'c.greensafe.o3': "برو داخل و بعد دست‌هایت را خوب بشوی.", // nagelezen (2e lezing) // nagelezen AI 22 nov
    'c.greensafe.w': "سم‌ها می‌توانند به پوست، چشم‌ها و ریه‌هایت آسیب بزنند، حتی وقتی بویی حس نمی‌کنی. بعد از سم‌پاشی یک زمان انتظار هست تا دوباره بشود داخل رفت. سرپرستت می‌داند کی تمام می‌شود.", // nagelezen (2e lezing) // nagelezen AI 22 nov
