    'c.road.a': "نه، آن وقت برای استراحتم وقت ندارم.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.parcel': "کسی خانه نیست، یا بسته خراب است", // nieuw, nalezen // nagelezen AI 22 nov
    'c.parcel.b': "مشتری خانه نیست؟ طبق قانون‌های شرکتت عمل کن: سراغ همسایه‌ها برو، یا بسته را برگردان. آن را همین‌طوری دم در نگذار، مگر اینکه مشتری این را خواسته باشد. بسته‌ای خراب یا خیس است؟ آن را طوری تحویل نده که انگار هیچ مشکلی نیست. به عنوان مدرک عکس بگیر، و آن را در اسکنر یا اپ گزارش بده. صادق بودن دربارهٔ یک مشکل همیشه بهتر از پنهان کردنش است. قانون‌ها در هر شرکت فرق دارد: از سرپرستت بپرس قانون‌های محل کارت چیست.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.parcel.p': "این بسته خراب است. این هم یک عکس.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.parcel.s': "مشتری خانه نیست، همسایه‌ها هم نیستند. چه کار می‌کنی؟", // nieuw, nalezen // nagelezen AI 22 nov
    'c.parcel.o1': "«خانه نیست» را اسکن می‌کنی و بسته را برمی‌گردانی.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.parcel.o2': "آن را «تحویل‌شده» اسکن می‌کنی و دم در می‌گذاری.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.parcel.o3': "آن را پشت سطل زباله قایم می‌کنی تا کسی نبیند.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.parcel.w': "بسته‌ای که «تحویل‌شده» اسکن شده، باید واقعاً دست مشتری باشد. وقتی چیزی را که واقعاً اتفاق افتاده اسکن کنی، مشتری می‌تواند بسته را بعداً بگیرد، و هیچ‌کس فکر نمی‌کند تو آن را گم کرده‌ای.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.road': "ایمن در جاده، و کار منصفانه", // nieuw, nalezen // nagelezen AI 22 nov
    'c.road.b': "هیچ‌وقت موقع رانندگی گوشی را دستت نگیر: این ممنوع است. برای مسیریابی از پایهٔ گوشی استفاده کن. استراحت‌هایت را بکن، حتی در یک روز شلوغ. بستهٔ سنگین؟ از چرخ دستی استفاده کن، یا با هم بلندش کنید. یخ یا برف؟ آهسته بران: دیر رسیدن بهتر از تصادف است. بعضی شرکت‌ها می‌گویند تو خویش‌فرما (zelfstandig) کار می‌کنی. ولی چه کسی ساعت‌ها، مسیر و لباست را تعیین می‌کند؟ اگر شرکت همهٔ این‌ها را تعیین کند، شاید در واقع حقوق‌بگیر (in loondienst) باشی. آن وقت اغلب حق‌های بیشتری داری، مثل حقوق وقتی مریضی. بیشتر دربارهٔ این در درس «مدارک، ادغام و کار تو». اطلاعات کلی. برای وضعیت خودت: از اتحادیهٔ کارگری، Juridisch Loket یا FairWork بپرس.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.road.p': "الان استراحتم را می‌کنم. بعد به راهم ادامه می‌دهم.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.road.s': "شرکت تو را خویش‌فرما می‌نامد. ولی ساعت‌ها، مسیر و لباست را خودش تعیین می‌کند. چه کار می‌کنی؟", // nieuw, nalezen // nagelezen AI 22 nov
    'c.road.o1': "مشورت می‌گیری: شاید حقوق‌بگیر باشی.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.road.o2': "هیچ کاری نمی‌کنی: در قرارداد نوشته خویش‌فرما، پس همین است.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.road.o3': "ساعت‌های بیشتری کار می‌کنی تا همان‌قدر درآمد داشته باشی.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.road.w': "مهم این است که واقعاً چطور کار می‌کنی، نه فقط کلمه‌ای که در قرارداد نوشته. اگر شرکت تعیین کند چطور، کی و کجا کار کنی، اغلب حقوق‌بگیر هستی. آن وقت حق‌های بیشتری داری.", // nieuw, nalezen // nagelezen AI 22 nov
