    'c.feelwell.b': "همه گاهی خسته، تحت فشار یا غمگین می‌شوند. کار خیلی زیاد (werkdruk)، خواب بد به خاطر کار شیفتی یا دلتنگی برای خانواده می‌تواند همه چیز را سنگین کند. لازم نیست این بار را تنهایی به دوش بکشی، و گفتن «خیلی زیاد است» ضعف نیست. با کسی که به او اعتماد داری حرف بزن. مثلاً سرپرستت، پزشک شرکت (bedrijfsarts) یا پزشک خانواده‌ات (huisarts). یا مشاور معتمد (vertrouwenspersoon)، اگر شرکتت چنین کسی دارد. خودت هم می‌توانی برای گفت‌وگو با پزشک شرکت وقت بخواهی. پزشک‌ها به رئیست نمی‌گویند تو چه گفته‌ای. به خودکشی فکر می‌کنی، یا نگران کسی هستی؟ به ۱۱۳ زنگ بزن (رایگان، شب و روز)، یا در 113.nl چت کن.", // nagelezen AI 22 nov
    'c.feelwell.p': "حالم زیاد خوب نیست. می‌توانم یک لحظه با تو حرف بزنم؟", // nieuw, nalezen // nagelezen AI 22 nov
    'c.feelwell.s': "چند هفته است که بد می‌خوابی و کار خیلی زیاد است. خیلی خسته‌ای. چه کار می‌کنی؟", // nieuw, nalezen // nagelezen AI 22 nov
