    'c.backtowork.b': "خوب شده‌ای؟ به کارفرما خبر بده که دوباره می‌توانی کار کنی (betermelden). بعد از یک بیماری طولانی‌تر، اغلب قدم به قدم شروع می‌کنی: اول ساعت‌های کمتر، یا کار سبک‌تر. پزشک شرکت (bedrijfsarts) دربارهٔ کارهایی که می‌توانی بکنی مشورت می‌دهد. مدت طولانی‌تری مریض بوده‌ای؟ آن وقت تو و کارفرما با هم برای برگشتنت برنامه‌ای می‌ریزید. این قانون است (Wet verbetering poortwachter). روشن بگو چه کاری از تو برمی‌آید، و چه کاری هنوز نه. لازم نیست به همکاران بگویی چه بیماری‌ای داشتی. اطلاعات کلی. برای وضعیت خودت: از کارفرما، اتحادیهٔ کارگری یا Juridisch Loket بپرس.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.backtowork.p': "این را دیگر می‌توانم. آن را هنوز نمی‌توانم.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.backtowork.s': "سه هفته مریض بودی. در اولین روز برگشتنت، سرپرستت از تو می‌خواهد جعبه‌های سنگین بلند کنی. پزشک شرکت گفته: فعلاً فقط کار سبک. چه کار می‌کنی؟", // nieuw, nalezen // nagelezen AI 22 nov
    'c.backtowork.o1': "آرام می‌گویی که حالا کار سبک می‌توانی بکنی، و چه کاری را هنوز نمی‌توانی.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.backtowork.o2': "با این حال جعبه‌ها را بلند می‌کنی: نمی‌خواهی دردسر درست کنی.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.backtowork.o3': "بدون یک کلمه به خانه می‌روی.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.backtowork.w': "سرپرستت می‌خواهد برگردی، آن هم سالم. وقتی روشن بگویی چه کاری از تو برمی‌آید، او می‌تواند کار را برنامه‌ریزی کند. زود زیاد کار کردن می‌تواند دوباره مریضت کند.", // nieuw, nalezen // nagelezen AI 22 nov
