    's.drawing.3': "دو میلی‌متر بزرگ است.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.drawing.q': "پیچ جا می‌رود؟", // nieuw, nalezen // nagelezen AI 28 nov
