    'c.drawing.w': "قطعه‌ای که با زور جا رفته ممکن است بعداً بشکند، پیش مشتری. وقتی خبر می‌دهی، می‌شود علت را پیدا کرد.", // nieuw, nalezen // nagelezen AI 22 nov
