    'c.tiletools.w': "چسب کاشی در وقت استراحت هم سفت می‌شود. مالهٔ دندانه‌دار تمیز شیارهای خوب درست می‌کند، و کاشی‌ها خوب می‌چسبند. چسب سفت روی آن یعنی کار زیاد، یا یک ابزار نو.", // nieuw, nalezen // nagelezen AI 22 nov
