    'c.upkeep.w': "نشتی بزرگ‌تر می‌شود، و روغن روی زمین باعث می‌شود آدم‌ها لیز بخورند. اگر زود پیدا شود، تعمیرش کوچک است.", // nieuw, nalezen // nagelezen AI 22 nov
