    'c.testing.w': "گاهی فیوز اشتباه قطع شده، یا کسی دوباره وصلش می‌کند. قفل و اندازه‌گیری نشان می‌دهند که واقعاً ایمن است.", // nieuw, nalezen // nagelezen AI 22 nov
