    'c.pipes.w': "یک قطره در دقیقه، در هفته چندین لیتر می‌شود. آب می‌تواند به کف یا به سقف طبقهٔ پایین آسیب بزند.", // nieuw, nalezen // nagelezen AI 22 nov
