    'c.metalwork.s': "باید در یک تکهٔ کوچک فلز سوراخ بزنی. گیرهٔ رومیزی روی یک میز دیگر است. چه کار می‌کنی؟", // nieuw, nalezen // nagelezen AI 22 nov
