    'c.access.w': "هر کسی می‌تواند بگوید مدیر است. یک بررسی کوتاه ساختمان را ایمن نگه می‌دارد، و یک مدیر واقعی درک می‌کند.", // nieuw, nalezen // nagelezen AI 28 nov
