    'c.aggression.s': "مردی سرت داد می‌زند و خیلی نزدیک می‌آید. چه کار می‌کنی؟", // nieuw, nalezen // nagelezen AI 28 nov
    'c.aggression.o1': "عقب می‌روی، و آرام حرف می‌زنی.", // nieuw, nalezen // nagelezen AI 28 nov
