    'c.binlorry.s': "خیابان بعدی خیلی نزدیک است. راننده می‌گوید: «روی رکاب عقب بایست». چه کار می‌کنی؟", // nieuw, nalezen // nagelezen AI 28 nov
    'c.binlorry.o1': "با این حال سوار کابین می‌شوی.", // nieuw, nalezen // nagelezen AI 28 nov
