    's.childsafety.1': "درِ محافظ پله را همیشه ببند.", // nieuw, nalezen // nagelezen AI 28 nov
    's.childsafety.2': "کمی یخ روی ورم می‌گذارم.", // nieuw, nalezen // nagelezen AI 28 nov
