    's.knives.3': "جعفری را ریز خرد کن.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.knives.q': "می‌توانی پیازها را خرد کنی؟", // nieuw, nalezen // nagelezen AI 28 nov
