    'w.zorgdossier': "پروندهٔ مراقبت (همه چیز دربارهٔ مراقبت از یک مراجع)", // nieuw, nalezen // nagelezen AI 28 nov
    'w.drukplek': "زخم فشاری (لکهٔ قرمز از دراز کشیدن یا نشستن طولانی)", // nieuw, nalezen // nagelezen AI 28 nov
